//
// The user guide's WebMCP index and tools (W2 of #2500).
//
// `web/guide/guide_index_<lang>.js` is generated by tool/build_guide_site.dart
// and must be what it produces today (the same drift check as the pages);
// `tool/guide/guide_webmcp_check.mjs` runs the tools against a fake
// modelContext in every language: every entry's anchor exists in its page,
// its text is the page's text, a section's title finds that section, an
// unknown id is not_found with suggestions, the page CSP is unchanged and no
// tool reaches for the network.
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import '../../tool/build_guide_site.dart' as site;

void main() {
  test('the guide indexes are what build_guide_site produces today', () {
    final expected = site.buildIndexes();
    expect(expected.keys.length, 5);
    final stale = site.staleOutputs(
      expected,
      (p) => File(p).existsSync() ? File(p).readAsStringSync() : null,
    );
    expect(
      stale,
      isEmpty,
      reason: 'run: dart run tool/build_guide_site.dart and commit the result',
    );
  });

  test('a stale or missing index is reported by the check', () {
    final expected = {'a.js': 'new', 'b.js': 'same', 'c.js': 'x'};
    final files = {'a.js': 'old', 'b.js': 'same'};
    expect(site.staleOutputs(expected, (p) => files[p]), ['a.js', 'c.js']);
  });

  test('one entry per line, so a paragraph change touches one line', () {
    final js = site.buildIndexes()['web/guide/guide_index_en.js']!;
    final lines = js.trimRight().split('\n');
    expect(lines.length, greaterThan(100));
    expect(lines.last, '];');
    expect(js, isNot(contains('</script')));
  });

  test('the indexed text is plain: no markup survives', () {
    expect(
      site.plainText('<p>One &amp; <a href="x">two</a></p><ul><li>a</li><li>b</li></ul>'),
      'One & two a b',
    );
  });

  test('the tools answer in every language, from the generated index', () {
    final r = Process.runSync('node', ['tool/guide/guide_webmcp_check.mjs']);
    final out = '${r.stdout}${r.stderr}';
    expect(r.exitCode, 0, reason: out);
    expect(out, contains('guide webmcp: ok'));
  });
}
